// Функция сортировки выбором
void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int min_idx = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        // Обмен местами найденного минимума и первого элемента
        int temp = arr[min_idx];
        arr[min_idx] = arr[i];
        arr[i] = temp;
    }
}

// Функция шейкер-сортировки (Cocktail Shaker Sort)
void cocktailSort(int arr[], int n) {
    int left = 0;
    int right = n - 1;
    int swapped = 1;

    while (swapped) {
        swapped = 0;
        // Проход слева направо
        for (int i = left; i < right; i++) {
            if (arr[i] > arr[i + 1]) {
                int temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = 1;
            }
        }
        if (!swapped) break;
        right--;

        swapped = 0;
        // Проход справа налево
        for (int i = right - 1; i >= left; i--) {
            if (arr[i] > arr[i + 1]) {
                int temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = 1;
            }
        }
        left++;
    }
}

